dtsPropsFor.MessageBubble:
/** Sender — controls bubble alignment and palette. */
  role: 'user' | 'assistant';
  /** Message text; supports multiline and streaming partials. */
  content: string;
  /** Assistant name shown above an assistant bubble. */
  characterName?: string;
  /** Show the blinking cursor while a reply streams in. */
  isStreaming?: boolean;

dtsPropsFor.ShopModal:
/** Controls visibility; renders nothing when false. */
  open: boolean;
  /** Player coin balance (gates affordability). */
  coins: number;
  /** Player decor-token balance (second currency). */
  tokens: number;
  onClose: () => void;
  /** Fires with the purchased catalog item. */
  onPurchase: (item: { type: string; label: string; description: string; icon: string; happiness: number; cost: number; tokenCost: number; draggable: boolean; category: 'essential' | 'decor' | 'entertainment' | 'wall' }) => void;

dtsPropsFor.SupplyPanel:
/** Controls visibility; renders nothing when false. */
  open: boolean;
  coins: number;
  /** Current food gauge value (0–40000). */
  food: number;
  /** Formatted countdown until the food gauge empties. */
  depletionLabel: string;
  onClose: () => void;
  /** Fires with the fed food item. */
  onFeed: (item: { id: string; label: string; icon: string; food: number; cost: number }) => void;

dtsPropsFor.FurnitureInspector:
/** Selected room object; renders nothing when null. */
  object: { id: number; furnitureType: string; label: string; description: string; wx: number; wy: number; wz: number; happiness: number; draggable: boolean } | null;
  onClose: () => void;
  /** Enter drag-to-move mode for the selected object. */
  onMoveMode: () => void;
  /** Delete the object by id. */
  onDelete: (id: number) => void;
